+const fetch = require('node-fetch');
+
+// Environment: set BASE_URL to the running backend (default: http://localhost:8080)
+const BASE_URL = process.env.BASE_URL || 'http://localhost:8080';
+
+function randomSuffix() {
+  return Math.random().toString(36).substring(2, 8);
+}
+
+async function postRegister(payload) {
+  const res = await fetch(`${BASE_URL}/api/v1/auth/register`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify(payload),
+  });
+  const text = await res.text();
+  let body = null;
+  try { body = JSON.parse(text); } catch (e) { body = text; }
+  return { status: res.status, body };
+}
+
+/* Test: 正常登録
+   - 登録に必要な全フィールドを送り、201 Created とユーザー情報が返ることを確認する */
+test('正常登録: returns 201 and user info', async () => {
+  const suffix = randomSuffix();
+  const payload = {
+    username: `user_${suffix}`,
+    email: `test_${suffix}@ginga.info`,
+    password: 'Aa1!aaaa',
+    displayName: 'テスト ユーザー'
+  };
+  const res = await postRegister(payload);
+  expect(res.status).toBe(201);
+  expect(res.body).toHaveProperty('id');
+  expect(res.body.username).toBe(payload.username);
+  expect(res.body.email).toBe(payload.email);
+});
+
+/* Test: メールドメイン検証
+   - @ginga.info ドメイン以外のメールアドレスを送ると 400 を返す */
+test('メールドメイン検証: invalid domain returns 400', async () => {
+  const payload = {
+    username: `user_bad_${randomSuffix()}`,
+    email: `bad@other.com`,
+    password: 'Aa1!aaaa',
+    displayName: 'Bad Domain'
+  };
+  const res = await postRegister(payload);
+  expect(res.status).toBe(400);
+});
+
+/* Test: パスワード強度検証
