+test('確認トークンフロー: register -> confirm -> user enabled', async () => {
+  const suffix = randomSuffix();
+  const email = `conf_${suffix}@ginga.info`;
+  const payload = {
+    username: `confuser_${suffix}`,
+    email: email,
+    password: 'Aa1!aaaa',
+    displayName: 'Confirm User'
+  };
